CREATE TABLE permission (code VARCHAR(80) PRIMARY KEY, name VARCHAR(100) NOT NULL, module VARCHAR(50) NOT NULL);
CREATE TABLE app_role (id VARCHAR(64) PRIMARY KEY, name VARCHAR(80) NOT NULL, data_scope VARCHAR(16) NOT NULL, builtin BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE role_permission (role_id VARCHAR(64) NOT NULL, permission_code VARCHAR(80) NOT NULL, PRIMARY KEY(role_id,permission_code), FOREIGN KEY(role_id) REFERENCES app_role(id), FOREIGN KEY(permission_code) REFERENCES permission(code));
CREATE TABLE app_user (id VARCHAR(64) PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, display_name VARCHAR(80) NOT NULL, password_hash VARCHAR(100) NOT NULL, store_id VARCHAR(64), enabled BOOLEAN NOT NULL, token_version INTEGER NOT NULL DEFAULT 0, created_at VARCHAR(40) NOT NULL);
CREATE TABLE user_role (user_id VARCHAR(64) NOT NULL, role_id VARCHAR(64) NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES app_user(id), FOREIGN KEY(role_id) REFERENCES app_role(id));
CREATE TABLE customer_identity (id VARCHAR(64) PRIMARY KEY, openid VARCHAR(160) NOT NULL UNIQUE, is_development BOOLEAN NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE site_config (id VARCHAR(32) PRIMARY KEY, revision INTEGER NOT NULL, published_json LONGTEXT NOT NULL, draft_json LONGTEXT NOT NULL);
CREATE TABLE store (id VARCHAR(64) PRIMARY KEY, name VARCHAR(100) NOT NULL, enabled BOOLEAN NOT NULL, profile_json LONGTEXT NOT NULL, rules_json LONGTEXT NOT NULL);
CREATE TABLE therapist (id VARCHAR(64) PRIMARY KEY, store_id VARCHAR(64) NOT NULL, name VARCHAR(80) NOT NULL, profile_json LONGTEXT NOT NULL, enabled BOOLEAN NOT NULL, FOREIGN KEY(store_id) REFERENCES store(id));
CREATE INDEX ix_therapist_store ON therapist(store_id);
CREATE TABLE slot_override (store_id VARCHAR(64) NOT NULL, booking_date VARCHAR(10) NOT NULL, start_time VARCHAR(5) NOT NULL, capacity INTEGER NOT NULL, closed BOOLEAN NOT NULL, PRIMARY KEY(store_id,booking_date,start_time), FOREIGN KEY(store_id) REFERENCES store(id));
CREATE TABLE appointment (id VARCHAR(64) PRIMARY KEY, customer_id VARCHAR(64), store_id VARCHAR(64) NOT NULL, service_id VARCHAR(64) NOT NULL, service_name VARCHAR(100) NOT NULL, customer_name VARCHAR(80) NOT NULL, phone VARCHAR(20) NOT NULL, booking_date VARCHAR(10) NOT NULL, start_time VARCHAR(5) NOT NULL, headcount INTEGER NOT NULL, therapist_intent_id VARCHAR(64), therapist_intent_name VARCHAR(80), assigned_therapist_id VARCHAR(64), member_claim VARCHAR(20) NOT NULL, visited_claim VARCHAR(20) NOT NULL, remark VARCHAR(500) NOT NULL, sensitive_consent BOOLEAN NOT NULL, status VARCHAR(24) NOT NULL, source VARCHAR(24) NOT NULL, version INTEGER NOT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, cancel_reason VARCHAR(500), idempotency_owner VARCHAR(80) NOT NULL, idempotency_key VARCHAR(100) NOT NULL, request_hash VARCHAR(64) NOT NULL, UNIQUE(idempotency_owner,idempotency_key), FOREIGN KEY(store_id) REFERENCES store(id));
CREATE INDEX ix_appointment_slot ON appointment(store_id,booking_date,start_time,status);
CREATE INDEX ix_appointment_customer ON appointment(customer_id,created_at);
CREATE INDEX ix_appointment_phone ON appointment(phone,status);
CREATE TABLE appointment_history (id VARCHAR(64) PRIMARY KEY, appointment_id VARCHAR(64) NOT NULL, status VARCHAR(24) NOT NULL, note VARCHAR(500) NOT NULL, operator_name VARCHAR(100) NOT NULL, created_at VARCHAR(40) NOT NULL, FOREIGN KEY(appointment_id) REFERENCES appointment(id));
CREATE TABLE customer_profile (id VARCHAR(64) PRIMARY KEY, phone VARCHAR(20) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL, member_verified BOOLEAN NOT NULL, member_grade VARCHAR(60) NOT NULL, original_store_id VARCHAR(64), shared_note VARCHAR(300) NOT NULL, external_id VARCHAR(80), created_at VARCHAR(40) NOT NULL);
CREATE TABLE store_customer (store_id VARCHAR(64) NOT NULL, customer_profile_id VARCHAR(64) NOT NULL, private_note VARCHAR(1000) NOT NULL, source VARCHAR(80) NOT NULL, preferred_therapist_id VARCHAR(64), PRIMARY KEY(store_id,customer_profile_id), FOREIGN KEY(store_id) REFERENCES store(id), FOREIGN KEY(customer_profile_id) REFERENCES customer_profile(id));
CREATE TABLE notification_recipient (store_id VARCHAR(64) PRIMARY KEY, admin_user_id VARCHAR(64) NOT NULL, openid VARCHAR(160), enabled BOOLEAN NOT NULL, generation INTEGER NOT NULL DEFAULT 1, FOREIGN KEY(store_id) REFERENCES store(id), FOREIGN KEY(admin_user_id) REFERENCES app_user(id));
CREATE TABLE service_binding (token VARCHAR(80) PRIMARY KEY, store_id VARCHAR(64) NOT NULL, admin_user_id VARCHAR(64) NOT NULL, expires_at VARCHAR(40) NOT NULL, used BOOLEAN NOT NULL);
CREATE TABLE subscription_grant (customer_id VARCHAR(64) NOT NULL, template_id VARCHAR(100) NOT NULL, remaining INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(customer_id,template_id));
CREATE TABLE notification_outbox (id VARCHAR(64) PRIMARY KEY, event_key VARCHAR(160) NOT NULL, store_id VARCHAR(64) NOT NULL, appointment_id VARCHAR(64) NOT NULL, channel VARCHAR(24) NOT NULL, recipient_id VARCHAR(160) NOT NULL, recipient_generation INTEGER NOT NULL DEFAULT 0, event_type VARCHAR(60) NOT NULL, payload_json LONGTEXT NOT NULL, delivery_status VARCHAR(30) NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, last_error VARCHAR(800), created_at VARCHAR(40) NOT NULL, next_attempt_at VARCHAR(40) NOT NULL, UNIQUE(event_key,channel,recipient_id));
CREATE INDEX ix_notification_work ON notification_outbox(delivery_status,next_attempt_at);
CREATE TABLE audit_log (id VARCHAR(64) PRIMARY KEY, actor_id VARCHAR(64) NOT NULL, actor_name VARCHAR(100) NOT NULL, store_id VARCHAR(64), action VARCHAR(80) NOT NULL, target_id VARCHAR(100), detail VARCHAR(800), created_at VARCHAR(40) NOT NULL);
CREATE TABLE asset (id VARCHAR(64) PRIMARY KEY, store_id VARCHAR(64), title VARCHAR(100) NOT NULL, url VARCHAR(300) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE app_setting (setting_key VARCHAR(80) PRIMARY KEY, setting_value VARCHAR(2000) NOT NULL);
CREATE TABLE pms_outbox (id VARCHAR(64) PRIMARY KEY, aggregate_id VARCHAR(64) NOT NULL, aggregate_version INTEGER NOT NULL, event_type VARCHAR(60) NOT NULL, schema_version INTEGER NOT NULL, store_id VARCHAR(64) NOT NULL, payload_json LONGTEXT NOT NULL, created_at VARCHAR(40) NOT NULL, acknowledged BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE(aggregate_id,aggregate_version,event_type));
